//! Interpolation via Newton divided differences + Horner expansion.
//!
//! Precomputed divided-difference weights are generated by
//! `sagemath/save_newton_weights_bin.sage`.

use super::gf2_9009::{GF29009_NUM_U64, Gf2_9009, POLY_MUL_SCRATCH, poly_mul, reduce};

/// Load precomputed Newton divided-difference weights from embedded binary data.
///
/// Format: 4 bytes (M as little-endian u32), then M*(M-1)/2 GF elements in
/// flat order: (s=1, i=1..M-1), (s=2, i=2..M-1), ..., (s=M-1, i=M-1).
/// weight[s][i] = 1 / (x[i] - x[i-s]) where x[k] = a^(k+1).
pub fn load_newton_weights<const M: usize>(data: &[u8]) -> Box<[Gf2_9009]> {
    let m = u32::from_le_bytes([data[0], data[1], data[2], data[3]]) as usize;
    assert_eq!(
        m, M,
        "Newton weight data size mismatch: expected {M}, got {m}"
    );
    let num_weights = M * (M - 1) / 2;
    let entry_size = GF29009_NUM_U64 * 8;
    let expected_len = 4 + num_weights * entry_size;
    assert_eq!(
        data.len(),
        expected_len,
        "Newton weight data length mismatch: expected {}, got {}",
        expected_len,
        data.len()
    );

    let mut weights = vec![Gf2_9009::zero(); num_weights].into_boxed_slice();
    let mut offset = 4;
    for w in weights.iter_mut() {
        let mut field_data = [0u64; GF29009_NUM_U64];
        for (j, f) in field_data.iter_mut().enumerate() {
            let start = offset + j * 8;
            *f = u64::from_le_bytes(data[start..start + 8].try_into().unwrap());
        }
        *w = Gf2_9009::new(field_data);
        offset += entry_size;
    }
    weights
}

/// Flat index for the divided-difference weight w[s][i] (s >= 1, i >= s).
///
/// Weights are stored in order: (s=1,i=1..M-1), (s=2,i=2..M-1), ...
/// Row s has M-s elements starting at offset (s-1)*M - s*(s-1)/2.
#[inline]
const fn newton_weight_idx(m: usize, s: usize, i: usize) -> usize {
    let offset = (s - 1) * m - s * (s - 1) / 2;
    offset + (i - s)
}

/// Apply Newton divided differences in-place.
///
/// After this, d[k] holds the k-th Newton coefficient c_k = f[x_0,...,x_k],
/// where x_k = a^(k+1) and weights[s][i] = 1/(x[i] - x[i-s]).
fn divided_differences<const M: usize>(d: &mut [Gf2_9009; M], weights: &[Gf2_9009]) {
    let mut scratch = [0u64; POLY_MUL_SCRATCH];
    for s in 1..M {
        // All updates within a step are independent (downward sweep reads old values).
        for i in (s..M).rev() {
            let w_idx = newton_weight_idx(M, s, i);
            let mut tmp = d[i];
            tmp.add(&d[i - 1]); // XOR: d[i] - d[i-1] = d[i] + d[i-1] in GF(2)
            let mut prod = [0u64; 2 * GF29009_NUM_U64];
            poly_mul(&tmp.data, &weights[w_idx].data, &mut prod, &mut scratch);
            reduce(&mut prod, &mut d[i]);
        }
    }
}

/// Convert Newton coefficients to monomial coefficients via Horner expansion.
///
/// p(t) = c_0 + c_1*(t-x_0) + c_2*(t-x_0)*(t-x_1) + ...
/// where x_k = a^(k+1) = the field polynomial x^(k+1) (sparse — one bit set).
///
/// Multiplying by (t - x_k) uses mul_by_x_pow(k+1) for the "x_k * coeff"
/// part, which is a cheap bit-shift + reduction rather than a full poly_mul.
fn newton_to_monomial<const M: usize>(c: &[Gf2_9009; M]) -> [Gf2_9009; M] {
    let mut poly = [Gf2_9009::zero(); M];
    poly[0] = c[M - 1]; // start with the outermost Newton coefficient

    for k in (0..M - 1).rev() {
        // Expand: poly <- poly * (t + x_k) + c[k]
        // where x_k = a^(k+1), so "* x_k" = mul_by_x_pow(k+1)
        let shift = k + 1;
        let degree = M - 2 - k; // current degree of poly before this step

        // Push the leading coefficient: new poly[degree+1] = old poly[degree]
        poly[degree + 1] = poly[degree];

        // Update poly[j] = old poly[j-1] + mul_by_x_pow(shift, old poly[j])
        // Process from high j to low so we read old values before overwriting.
        for j in (1..=degree).rev() {
            let mut shifted = Gf2_9009::zero();
            poly[j].mul_by_x_pow(shift, &mut shifted);
            poly[j] = poly[j - 1];
            poly[j].add(&shifted);
        }

        // poly[0] = c[k] + mul_by_x_pow(shift, old poly[0])
        let mut shifted = Gf2_9009::zero();
        poly[0].mul_by_x_pow(shift, &mut shifted);
        poly[0] = c[k];
        poly[0].add(&shifted);
    }

    poly
}

/// Interpolate `M` GF(2^9009) evaluation points into `M` monomial coefficients
/// using Newton divided differences + Horner expansion.
///
/// Uses M*(M-1)/2 full GF multiplications (divided differences) plus
/// M*(M-1)/2 cheap mul_by_x_pow shifts (Horner expansion), totalling roughly
/// half the expensive multiplications of a direct matrix method.
pub fn interpolate_newton<const M: usize>(
    weights: &[Gf2_9009],
    evals: &[Gf2_9009; M],
) -> [Gf2_9009; M] {
    debug_assert_eq!(weights.len(), M * (M - 1) / 2);
    let mut d = *evals;
    divided_differences::<M>(&mut d, weights);
    newton_to_monomial::<M>(&d)
}
